}

export enum ModelType {
  CODING = 'gemini-3-pro-preview',
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { ModelType } from '../types';

const SYSTEM_INSTRUCTION = `You are my Cybersecurity Coding Assistant for HackTheBox practice. 
Your job is to generate clean, well‑commented, defensive‑security scripts that help me learn, analyze, and understand systems inside legally authorized HTB labs.

Rules:
- Only produce code that is allowed in ethical hacking environments.
- Never generate or suggest anything illegal or intended for real-world unauthorized access.
- All scripts must be for learning, enumeration, analysis, automation, or reporting inside HTB.
- Always explain what the code does and why it is useful.
- Prefer Python, Bash, or PowerShell unless I request another language.
- Keep output modular, readable, and easy to modify.
- When I ask for a tool, generate:
  1. A clear description of the tool’s purpose
  2. The full code
  3. Usage examples
  4. Optional improvements I can add later

Capabilities you should support:
- Port scanning (legal environments only)
- Service enumeration
- File parsing
- Log analysis
- Encoding/decoding utilities
- Hash identification
- Wordlist manipulation
- Report generation
- Automation helpers for repetitive HTB tasks

Stay in teaching mode:
- Explain concepts simply
- Highlight common pitfalls
- Suggest next steps in the learning process

Begin every response with: "HTB Assistant Ready."`;

class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat | null = null;

  constructor() {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.error("API_KEY not found in environment variables");
    }
    // Initialize with the API key from environment variables
    this.ai = new GoogleGenAI({ apiKey: apiKey || 'dummy-key-for-init' });
  }

  public initializeChat() {
    this.chatSession = this.ai.chats.create({
      model: ModelType.CODING,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        maxOutputTokens: 8192, // High limit for long scripts
      },
    });
  }

  public async sendMessageStream(message: string): Promise<AsyncIterable<string>> {
    if (!this.chatSession) {
      this.initializeChat();
    }

    if (!this.chatSession) {
      throw new Error("Failed to initialize chat session");
    }

    try {
      const result = await this.chatSession.sendMessageStream({ message });

      return {
        async *[Symbol.asyncIterator]() {
          for await (const chunk of result) {
            const responseChunk = chunk as GenerateContentResponse;
            if (responseChunk.text) {
              yield responseChunk.text;
            }
          }
        }
      };
    } catch (error) {
      console.error("Error sending message to Gemini:", error);
      throw error;
    }
  }
}

export const geminiService = new GeminiService();

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { PrismLight as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import bash from 'react-syntax-highlighter/dist/esm/languages/prism/bash';
import python from 'react-syntax-highlighter/dist/esm/languages/prism/python';
import powershell from 'react-syntax-highlighter/dist/esm/languages/prism/powershell';
import typescript from 'react-syntax-highlighter/dist/esm/languages/prism/typescript';
import json from 'react-syntax-highlighter/dist/esm/languages/prism/json';

// Register languages
SyntaxHighlighter.registerLanguage('bash', bash);
SyntaxHighlighter.registerLanguage('python', python);
SyntaxHighlighter.registerLanguage('powershell', powershell);
SyntaxHighlighter.registerLanguage('typescript', typescript);
SyntaxHighlighter.registerLanguage('json', json);

interface MarkdownRendererProps {
  content: string;
}

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content }) => {
  return (
    <ReactMarkdown
      components={{
        code({ node, inline, className, children, ...props }: any) {
          const match = /language-(\w+)/.exec(className || '');
          return !inline && match ? (
            <div className="relative group rounded-md overflow-hidden my-4 border border-gray-700">
              <div className="flex justify-between items-center px-4 py-1.5 bg-gray-800 border-b border-gray-700 text-xs text-gray-400 font-mono">
                <span>{match[1]}</span>
                <button
                    onClick={() => navigator.clipboard.writeText(String(children).replace(/\n$/, ''))}
                    className="hover:text-htb-accent transition-colors"
                    title="Copy Code"
                >
                    Copy
                </button>
              </div>
              <SyntaxHighlighter
                style={vscDarkPlus}
                language={match[1]}
                PreTag="div"
                customStyle={{ margin: 0, borderRadius: 0, padding: '1rem', fontSize: '0.9em' }}
                {...props}
              >
                {String(children).replace(/\n$/, '')}
              </SyntaxHighlighter>
            </div>
          ) : (
            <code className={`${className} bg-gray-800 text-htb-accent px-1.5 py-0.5 rounded text-sm font-mono`} {...props}>
              {children}
            </code>
          );
        },
        // Styling other markdown elements
        h1: ({node, ...props}) => <h1 className="text-2xl font-bold text-white mt-6 mb-4 border-b border-gray-700 pb-2" {...props} />,
        h2: ({node, ...props}) => <h2 className="text-xl font-bold text-white mt-5 mb-3" {...props} />,
        h3: ({node, ...props}) => <h3 className="text-lg font-bold text-white mt-4 mb-2" {...props} />,
        p: ({node, ...props}) => <p className="mb-4 leading-relaxed text-gray-300" {...props} />,
        ul: ({node, ...props}) => <ul className="list-disc list-inside mb-4 space-y-1 text-gray-300" {...props} />,
        ol: ({node, ...props}) => <ol className="list-decimal list-inside mb-4 space-y-1 text-gray-300" {...props} />,
        a: ({node, ...props}) => <a className="text-htb-accent hover:underline" target="_blank" rel="noopener noreferrer" {...props} />,
        blockquote: ({node, ...props}) => <blockquote className="border-l-4 border-htb-accent pl-4 italic text-gray-400 my-4 bg-gray-800/50 py-2 rounded-r" {...props} />,
      }}
    >
      {content}
    </ReactMarkdown>
  );
};

export default MarkdownRenderer;

