import React, { useState, useRef, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Message } from '../types';
import MarkdownRenderer from './MarkdownRenderer';
import { v4 as uuidv4 } from 'uuid';

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'model',
      content: 'HTB Assistant Ready. Awaiting instructions for enumeration, analysis, or scripting tasks.',
      timestamp: Date.now()
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: uuidv4(),
      role: 'user',
      content: input,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    const modelMessageId = uuidv4();
    const initialModelMessage: Message = {
        id: modelMessageId,
        role: 'model',
        content: '',
        timestamp: Date.now(),
        isStreaming: true
    };

    setMessages(prev => [...prev, initialModelMessage]);

    try {
        const stream = await geminiService.sendMessageStream(userMessage.content);

        let fullContent = '';

        for await (const chunk of stream) {
            fullContent += chunk;
            setMessages(prev => 
                prev.map(msg => 
                    msg.id === modelMessageId 
                        ? { ...msg, content: fullContent } 
                        : msg
                )
            );
        }

        setMessages(prev => 
            prev.map(msg => 
                msg.id === modelMessageId 
                    ? { ...msg, isStreaming: false } 
                    : msg
            )
        );

    } catch (error) {
        console.error("Chat error:", error);
        setMessages(prev => [
            ...prev, 
            {
                id: uuidv4(),
                role: 'system',
                content: "Error: Connection lost or API limit reached. Please check your configuration.",
                timestamp: Date.now()
            }
        ]);
    } finally {
        setIsTyping(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-htb-dark text-gray-200">

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div 
              className={`max-w-[90%] md:max-w-[80%] rounded-lg p-5 shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-blue-900/40 border border-blue-800/50 text-gray-100 rounded-tr-none' 
                  : msg.role === 'system'
                  ? 'bg-red-900/20 border border-red-800 text-red-300'
                  : 'bg-htb-panel border border-gray-700 text-gray-100 rounded-tl-none'
              }`}
            >
              {/* Header for Bot messages */}
              {msg.role === 'model' && (
                <div className="flex items-center gap-2 mb-3 pb-2 border-b border-gray-700/50">
                   <div className="w-5 h-5 rounded bg-htb-accent flex items-center justify-center text-htb-dark text-xs font-bold font-mono">AI</div>
                   <span className="text-htb-accent font-mono text-xs font-bold uppercase tracking-wider">HTB Assistant</span>
                </div>
              )}

              {msg.role === 'user' ? (
                <div className="whitespace-pre-wrap font-sans text-base leading-relaxed">
                  {msg.content}
                </div>
              ) : (
                <div className="text-sm md:text-base">
                  <MarkdownRenderer content={msg.content} />
                  {msg.isStreaming && (
                    <span className="inline-block w-2 h-4 ml-1 align-middle bg-htb-accent animate-pulse" />
                  )}
                </div>
              )}

              <div className="mt-2 text-right">
                <span className="text-[10px] text-gray-500 font-mono">
                    {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                </span>
              </div>
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 md:p-6 bg-htb-panel border-t border-gray-700">
        <div className="max-w-5xl mx-auto relative">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Ask for scripts, analysis, or explanations..."
            className="w-full bg-htb-dark text-gray-100 rounded-lg pl-4 pr-14 py-4 focus:outline-none focus:ring-1 focus:ring-htb-accent border border-gray-600 resize-none font-mono text-sm h-14 max-h-48 overflow-y-auto shadow-inner"
            disabled={isTyping}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className={`absolute right-2 top-2 bottom-2 px-4 rounded-md flex items-center justify-center transition-all ${
              !input.trim() || isTyping 
                ? 'text-gray-600 cursor-not-allowed' 
                : 'text-htb-accent hover:bg-htb-accent/10 hover:text-emerald-300'
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
            </svg>
          </button>
        </div>
        <p className="text-center text-xs text-gray-500 mt-2 font-mono">
           Input generated code only into authorized HTB environments.
        </p>
      </div>
    </div>
  );
};

export default ChatInterface;

