import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { ModelType } from '../types';

const SYSTEM_INSTRUCTION = `You are an elite Cybersecurity Coding Assistant (Pro Mode).
Your purpose is to generate high-performance, defensive-security scripts and analysis for authorized HTB operations.

OPERATIONAL PARAMETERS (PRO MODE):
- User Level: Expert / Senior Operator.
- Tone: Concise, technical, no-fluff.
- Constraints: Ethical/Legal use only (Authorized Lab/CTF environments).

CORE DIRECTIVES:
1. **Code First**: Prioritize generating complete, robust scripts over long explanations.
2. **Defensive Focus**: Scripts should focus on enumeration, analysis, hardening, and forensic auditing.
3. **Modularity**: Code should be modular, error-handled, and ready for integration into larger toolchains.
4. **Safety**: Never generate malware or exploit payloads. Focus on the mechanism of action for understanding, not weaponization.

CAPABILITIES:
- Advanced Nmap/Masscan automation strategies.
- Custom packet crafting (Python/Scapy).
- Log parsing & SIEM rule generation (Sigma/YARA).
- Binary analysis helpers (Ghidra/Radare2 scripts).
- Active Directory enumeration (PowerShell/LDAP).
- Web fuzzing & payload encoding.

When asked for a tool/script:
- Provide the code immediately.
- Brief inline comments explaining complex logic.
- Usage one-liner.

Begin responses with: ">> ASSISTANT_PRO_ONLINE"`;

class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat | null = null;

  constructor() {
    // Fix: Using process.env.API_KEY directly to initialize GoogleGenAI as required by SDK guidelines.
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  public initializeChat() {
    this.chatSession = this.ai.chats.create({
      model: ModelType.CODING,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.5, // Lower temperature for more deterministic/technical output
        // Removed maxOutputTokens to prevent potential blocking of thinking-augmented responses.
      },
    });
  }

  public async sendMessageStream(message: string): Promise<AsyncIterable<string>> {
    if (!this.chatSession) {
      this.initializeChat();
    }

    if (!this.chatSession) {
      throw new Error("Failed to initialize chat session");
    }

    try {
      const result = await this.chatSession.sendMessageStream({ message });

      return {
        async *[Symbol.asyncIterator]() {
          for await (const chunk of result) {
            // Fix: Accessed the .text property directly instead of calling it as a method.
            const responseChunk = chunk as GenerateContentResponse;
            if (responseChunk.text) {
              yield responseChunk.text;
            }
          }
        }
      };
    } catch (error) {
      console.error("Error sending message to Gemini:", error);
      throw error;
    }
  }
}

export const geminiService = new GeminiService();

